  "businessIntent": "Create a new khata account for Ramesh and record ₹500 credit on his account",
  "objectives": [
    {
      "objectiveId": "obj_khata_create_and_record_credit",
      "objectiveDescription": "Create a new khata account for Ramesh and record ₹500 credit",
      "capabilityId": "khata",
      "dependencies": []
    }
  ]
}

Plan version: 1

Objective results (full CapabilityResult per objective):
{
  "objectives": {
    "obj_khata_create_and_record_credit": {
      "status": "error",
      "result": {
        "status": "error",
        "diagnostics": "Invariant violation: create_customer requires prior query_khata"
      }
    }
  }
}

